use super::*;
#[test]
fn original_persistent_builder_close_preserves_real_child_work_and_empty_scan_custody(){
 let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&row["stock"];let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=s["fuel"].as_u64().unwrap();let mut owner=PersistentListBuilder::<u64>::new(1);let value=row["value"].as_u64().unwrap();let turn=SealedShared::admit(value,crate::shared_issuance::SharedIssuer::owned(),RetainedCloneGrant{maximum_items:1,..bank});fuel=fuel.checked_sub(turn.work).unwrap();let(shared,p)=turn.result.map_err(|(error,_)|error).unwrap();bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;assert_eq!(serde_json::to_value(*shared.get()).unwrap(),row["value"]);let mut shared=Some(shared);let turn=owner.adopt(&mut shared,RetainedCloneGrant{maximum_items:1,..bank});fuel=fuel.checked_sub(turn.work).unwrap();let p=turn.result.unwrap().unwrap();bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;owner.begin_close();let pointer=owner.rows[0].as_ref().unwrap().identity();let denied=owner.close_step(Default::default());assert_eq!(denied.work,row["deniedWork"].as_u64().unwrap());assert_eq!(owner.rows[0].as_ref().unwrap().identity(),pointer);
 for _ in 0..s["maximumTurns"].as_u64().unwrap(){if owner.terminal_is_empty(){break}let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||owner.close_step(RetainedCloneGrant{maximum_items:1,..bank}));assert!(turn.work<=1);fuel=fuel.checked_sub(turn.work).unwrap();let p=turn.result.unwrap().progress();assert!(p.fits(bank));assert_eq!((p.retained_capacity_bytes,p.released_bytes),heap);bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;}
 assert!(owner.terminal_is_empty());let cached=owner.close_step(Default::default());assert_eq!(cached.work,row["cachedWork"].as_u64().unwrap());assert_eq!(cached.result.unwrap().progress(),Default::default());
}
